(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.slotforgeSnapshot=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
 const check=(v,m)=>{if(!v)throw Error(m);};
 function clone(value){if(value===null||typeof value!=='object')return value;if(Array.isArray(value))return value.map(clone);return Object.fromEntries(Object.keys(value).map(key=>[key,clone(value[key])]));}
 function apply(db,changes){const copy=clone(db);check(Array.isArray(changes)&&changes.length<=200000,'Invalid club changes.');for(const c of changes){check(Array.isArray(c.path)&&c.path.length>0&&c.path.length<40,'Invalid change path.');check(c.path.every(k=>(typeof k==='string'&&!['__proto__','prototype','constructor'].includes(k))||(Number.isSafeInteger(k)&&k>=0)),'Invalid change key.');let obj=copy;for(const k of c.path.slice(0,-1)){check(obj&&Object.hasOwn(obj,k),'Missing change parent.');obj=obj[k];}const k=c.path.at(-1);if(c.order){check(Array.isArray(obj[k])&&Array.isArray(c.order)&&Array.isArray(c.records)&&new Set(c.order).size===c.order.length,'Invalid record changes.');const records=new Map(obj[k].map(x=>[x.id,x]));for(const r of c.records){check(typeof r.id==='string','Invalid record identity.');records.set(r.id,r.changes?apply(records.get(r.id),r.changes):clone(r.value));check(records.get(r.id)?.id===r.id,'Changed record identity.');}obj[k]=c.order.map(id=>{check(records.has(id),'Missing changed record.');return records.get(id);});}else if(c.trim!==undefined){check(Array.isArray(obj[k])&&Number.isSafeInteger(c.trim)&&c.trim>=0&&c.trim<=obj[k].length,'Invalid array change.');obj[k].length=c.trim;}else if(c.remove)delete obj[k];else{check(Object.hasOwn(c,'value'),'Missing change value.');obj[k]=clone(c.value);}}return copy;}
 return {apply};
});
